insert into public.iching_hexagrams(number,line_bits,payload) values (1,63,'{"name":"乾","judgment":"元亨。利貞。","image":"天行健，君子以自強不息。","yaoTexts":["初九：潛龍勿用。","九二：見龍在田，利見大人。","九三：君子終日乾乾，夕惕若；厲，无咎。","九四：或躍在淵，无咎。","九五：飛龍在天，利見大人。","上九：亢龍，有悔。"],"useText":"用九：見羣龍无首，吉。","sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2404991","sourceTitle":"《周易》乾卦 · 经文与大象","sourceRevision":2404991,"sourceSha256":"e8b8c4a93f7e1f86e00e83635a12423da0e134ec463ea21837f6a41b41661156","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"乾"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (2,0,'{"name":"坤","judgment":"元亨。利牝馬之貞。君子有攸往，先迷後得主。利西南得朋，東北喪朋。安貞，吉。","image":"地勢坤，君子以厚德載物。","yaoTexts":["初六：履霜，堅冰至。","六二：直方大，不習无不利。","六三：含章，可貞。或從王事，无成有終。","六四：括囊，无咎无譽。","六五：黃裳，元吉。","上六：龍戰于野，其血玄黃。"],"useText":"用六：利永貞。","sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2404999","sourceTitle":"《周易》坤卦 · 经文与大象","sourceRevision":2404999,"sourceSha256":"a229442f54886cd2b21b1b6ab19cb377c4c59e5fcd8ac6b75f44b846459ca881","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"坤"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (3,17,'{"name":"屯","judgment":"元亨，利貞。勿用有攸往，利建侯。","image":"雲雷，屯；君子以經綸。","yaoTexts":["初九：磐桓，利居貞，利建侯。","六二：屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。","六三：即鹿无虞，惟入于林中，君子幾不如舍，往吝。","六四：乘馬班如，求婚媾，往，吉无不利。","九五：屯其膏；小貞吉，大貞凶。","上六：乘馬班如，泣血漣如。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643482","sourceTitle":"《周易》屯卦 · 经文与大象","sourceRevision":10643482,"sourceSha256":"46e879adeb27dcbf7d8b7d0763fddf786025ad617ea3dccf364195467e8c4096","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"屯"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (4,34,'{"name":"蒙","judgment":"亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。","image":"山下出泉，蒙；君子以果行育德。","yaoTexts":["初六：發蒙，利用刑人，用說桎梏，以往吝。","九二：包蒙吉，納婦吉，子克家。","六三：勿用取女，見金夫，不有躬，无攸利。","六四：困蒙，吝。","六五：童蒙，吉。","上九：擊蒙，不利為寇，利禦寇。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645379","sourceTitle":"《周易》蒙卦 · 经文与大象","sourceRevision":10645379,"sourceSha256":"82968b32bb6552880209f9578ada9d2e30beadcc1fd2c59ee7d331c48dc9ea7b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"蒙"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (5,23,'{"name":"需","judgment":"有孚，光亨。貞吉，利涉大川。","image":"雲上於天，需；君子以飲食宴樂。","yaoTexts":["初九：需于郊，利用恆，无咎。","九二：需于沙，小有言，終吉。","九三：需于泥，致寇至。","六四：需于血，出自穴。","九五：需于酒食，貞吉。","上六：入于穴，有不速之客三人來，敬之終吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643261","sourceTitle":"《周易》需卦 · 经文与大象","sourceRevision":10643261,"sourceSha256":"ccff1d03f4da5a90b388b3ec308fef5aa49ad588ad480be8627d633a3ad5bac3","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"需"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (6,58,'{"name":"讼","judgment":"有孚，窒，惕，中吉，終凶。利見大人，不利涉大川。","image":"天與水違行，訟；君子以作事謀始。","yaoTexts":["初六：不永所事，小有言，終吉。","九二：不克訟，歸而逋，其邑人三百戶无眚。","六三：食舊德，貞厲，終吉。或從王事，无成。","九四：不克訟，復即命渝，安貞吉。","九五：訟，元吉。","上九：或錫之鞶帶，終朝三褫之。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645409","sourceTitle":"《周易》訟卦 · 经文与大象","sourceRevision":10645409,"sourceSha256":"8c6b14ac0b22d80ed48dd164132905c4dbdec9b3dda633744271e4bef064ee81","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"訟"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (7,2,'{"name":"师","judgment":"貞丈人吉，无咎。","image":"地中有水，師；君子以容民畜衆。","yaoTexts":["初六：師出以律，否臧，凶。","九二：在師中吉，无咎；王三錫命。","六三：師或輿尸，凶。","六四：師左次，无咎。","六五：田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。","上六：大君有命，開國承家，小人勿用。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405011","sourceTitle":"《周易》師卦 · 经文与大象","sourceRevision":2405011,"sourceSha256":"131b206cbc0995b1adfdab9560e66d7843fd85e3172bb4e9f89bb37e4665c1f9","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"師"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (8,16,'{"name":"比","judgment":"吉。原筮元永貞，无咎。不寧方來，後夫凶。","image":"地上有水，比；先王以建萬國，親諸侯。","yaoTexts":["初六：有孚，比之，无咎。有孚盈缶，終來有它，吉。","六二：比之自內，貞吉。","六三：比之匪人。","六四：外比之，貞吉。","九五：顯比。王用三敺，失前禽，邑人不誡，吉。","上六：比之无首，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645543","sourceTitle":"《周易》比卦 · 经文与大象","sourceRevision":10645543,"sourceSha256":"c722de4c7a95194e064b0c39c40c4712af8f007bf2186bc0d4f207e1fb0406e0","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"比"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (9,55,'{"name":"小畜","judgment":"亨。密雲不雨，自我西郊。","image":"風行天上，小畜，君子以懿文德。","yaoTexts":["初九：復自道，何其咎，吉。","九二：牽復，吉。","九三：車說輹，夫妻反目。","六四：有孚，血去惕出，无咎。","九五：有孚攣如，富以其鄰。","上九：既雨既處，尚得載，婦貞厲，月幾望，君子征凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645530","sourceTitle":"《周易》小畜卦 · 经文与大象","sourceRevision":10645530,"sourceSha256":"6e1e827c09da249c5391f31c860080fd05657107b62c7e109c31a038349aebb9","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"小畜"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (10,59,'{"name":"履","judgment":"履虎尾，不咥人，亨。","image":"上天下澤，履；君子以辨上下，定民志。","yaoTexts":["初九：素履，往无咎。","九二：履道坦坦，幽人貞吉。","六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。","九四：履虎尾，愬愬終吉。","九五：夬履，貞厲。","上九：視履考詳，其旋元吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647513","sourceTitle":"《周易》履卦 · 经文与大象","sourceRevision":10647513,"sourceSha256":"4cba3bd1b9e4d13bb34a71531611e37bebb7801d8e783c86870912540453cd49","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"履"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (11,7,'{"name":"泰","judgment":"小往大來，吉亨。","image":"天地交，泰；后以財成天地之道，輔相天地之宜，以左右民。","yaoTexts":["初九：拔茅茹以其彙，征吉。","九二：包荒。用馮河，不遐遺；朋亡。得尚于中行。","九三：无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。","六四：翩翩，不富以其鄰；不戒以孚。","六五：帝乙歸妹，以祉，元吉。","上六：城復于隍，勿用師，自邑告命，貞吝。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2106138","sourceTitle":"《周易》泰卦 · 经文与大象","sourceRevision":2106138,"sourceSha256":"ecd49dba63369af09ab717293badc4b5823106b89c25ee5ebed44466817616e7","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"泰"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (12,56,'{"name":"否","judgment":"否之匪人，不利君子貞，大往小來。","image":"天地不交，否；君子以儉德辟難，不可榮以祿。","yaoTexts":["初六，拔茅茹以其彙，貞吉。亨。","六二，包承，小人吉，大人否。亨。","六三，包羞。","九四，有命，无咎，疇離祉。","九五，休否，大人吉。其亡其亡，繫于包桑。","上九，傾否，先否後喜。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645603","sourceTitle":"《周易》否卦 · 经文与大象","sourceRevision":10645603,"sourceSha256":"40db949fcb2f204562ec6ba5377425cbc4261c46cc04e0748fdf399d5bb56fef","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"否"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (13,61,'{"name":"同人","judgment":"同人于野，亨。 利涉大川，利君子貞。","image":"天與火，同人；君子以類族辨物。","yaoTexts":["初九：同人于門，無咎。","六二：同人于宗，吝。","九三：伏戎于莽，升其高陵，三歲不興。","九四：乘其庸，弗克攻，吉。","九五：同人，先號啕而後笑。大師克相遇。","上九：同人于郊，無悔。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645635","sourceTitle":"《周易》同人卦 · 经文与大象","sourceRevision":10645635,"sourceSha256":"c60417d5fd75abf7a958e368c092afadb2357e0d1af69085a1abe990c05a3d37","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"同人"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (14,47,'{"name":"大有","judgment":"元亨。","image":"火在天上，大有；君子以遏惡揚善，順天休命。","yaoTexts":["初九：无交害，匪咎，艱則无咎。","九二：大轝以載，有攸往，无咎。","九三：公用亨于天子，小人弗克。","九四：匪其尫，无咎。","六五：厥孚交如，威如；吉。","上九：自天佑之，吉无不利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645712","sourceTitle":"《周易》大有卦 · 经文与大象","sourceRevision":10645712,"sourceSha256":"3c4fdab8bfd0a57bfe53c483c5ad32a308d58094167a8dbb52b16c8c4c26ef0c","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"大有"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (15,4,'{"name":"谦","judgment":"亨，君子有終。","image":"地中有山，謙；君子以裒多益寡，稱物平施。","yaoTexts":["初六：謙謙君子，用涉大川，吉。","六二：鳴謙，貞吉。","九三：勞謙君子，有終吉。","六四：无不利，撝謙。","六五：不富，以其鄰，利用侵伐，无不利。","上六：鳴謙，利用行師，征邑國。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2106142","sourceTitle":"《周易》謙卦 · 经文与大象","sourceRevision":2106142,"sourceSha256":"2ffb3b0269b10fe966f76b4dd96b49503733677215fa6b9df7414a0a903d3700","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"謙"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (16,8,'{"name":"豫","judgment":"利建侯行師。","image":"雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。","yaoTexts":["初六：鳴豫，凶。","六二：介于石，不終日，貞吉。","六三：盱豫，悔。遲有悔。","九四：由豫，大有得。勿疑。朋盍戠。","六五：貞疾，恆不死。","上六：冥豫，成有渝，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645735","sourceTitle":"《周易》豫卦 · 经文与大象","sourceRevision":10645735,"sourceSha256":"65bf434245ce44f90a7034ebef4159cd64b85f7cdb099c7f52e8820215bbfe5b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"豫"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (17,25,'{"name":"随","judgment":"元亨。利貞。无咎。","image":"澤中有雷，隨；君子以嚮晦入宴息。","yaoTexts":["初九：官有渝，貞吉。出門交有功。","六二：係小子，失丈夫。","六三：係丈夫，失小子。隨，有求得利，居貞。","九四：隨有獲，貞凶。有孚在道，以明，何咎。","九五：孚于嘉，吉。","上六：拘係之，乃從維之。王用亨于西山。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645020","sourceTitle":"《周易》隨卦 · 经文与大象","sourceRevision":10645020,"sourceSha256":"af3531608314476f887b4c8adc97ccf6c2ca09abf5718d4643be598cdda4a8d0","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"隨"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (18,38,'{"name":"蛊","judgment":"元亨。利涉大川。先甲三日，後甲三日。","image":"山下有風，蠱；君子以振民育德。","yaoTexts":["初六：幹父之蠱，有子考，无咎，厲終吉。","九二：幹母之蠱，不可貞。","九三：幹父之蠱，小有悔，无大咎。","六四：裕父之蠱，往見吝。","六五：幹父之蠱，用譽。","上九：不事王侯，高尚其事。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2106145","sourceTitle":"《周易》蠱卦 · 经文与大象","sourceRevision":2106145,"sourceSha256":"b823e1f7c186f7ae3ea27e22955595a873311c8c8f1c00a1b09d00f887df6a5a","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"蠱"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (19,3,'{"name":"临","judgment":"元亨。利貞。至于八月有凶。","image":"澤上有地，臨；君子以教思无窮，容保民无疆。","yaoTexts":["初九：咸臨，貞吉。","九二：咸臨，吉无不利。","六三：甘臨，无攸利。既憂之，无咎。","六四：至臨，无咎。","六五：知臨，大君之宜，吉。","上六：敦臨，吉无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2106146","sourceTitle":"《周易》臨卦 · 经文与大象","sourceRevision":2106146,"sourceSha256":"beadffbfc5356c83e7068507a7446efbe4c175eeec1c3845ec634e288f3217cc","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"臨"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (20,48,'{"name":"观","judgment":"盥而不薦，有孚顒若。","image":"風行地上，觀；先王以省方，觀民設教。","yaoTexts":["初六：童觀，小人无咎，君子吝。","六二：窺觀，利女貞。","六三：觀我生，進退。","六四：觀國之光，利用賓于王。","九五：觀我生，君子无咎。","上九：觀其生，君子无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645159","sourceTitle":"《周易》觀卦 · 经文与大象","sourceRevision":10645159,"sourceSha256":"73da70d9f76cf58dc6ff2ca031e27125ef50b80fca221ffdf082e28fe044de6e","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"觀"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (21,41,'{"name":"噬嗑","judgment":"亨。利用獄。","image":"雷電噬嗑；先王以明罰敕法。","yaoTexts":["初九：屨校滅趾，无咎。","六二：噬膚滅鼻，无咎。","六三：噬昔肉，遇毒；小吝，无咎。","九四：噬乾胏，得金矢，利艱貞，吉。","六五：噬乾肉，得黃金，貞厲，无咎。","上九：何校滅耳，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645753","sourceTitle":"《周易》噬嗑卦 · 经文与大象","sourceRevision":10645753,"sourceSha256":"cbfa0c3f32152b3c31c91624dddc4abd7b8217b7121507fecb8a68d7dc68ecee","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"噬嗑"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (22,37,'{"name":"贲","judgment":"亨。小利有攸往。","image":"山下有火，賁；君子以明庶政，无敢折獄。","yaoTexts":["初九：賁其趾，舍車而徒。","六二：賁其須。","九三：賁如濡如，永貞吉。","六四：賁如皤如，白馬翰如，匪寇婚媾。","六五：賁於丘園，束帛戔戔，吝，終吉。","上九：白賁，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405035","sourceTitle":"《周易》賁卦 · 经文与大象","sourceRevision":2405035,"sourceSha256":"f7418a0d3805c366e3afc6e9c7fb32c0c1da7883bf714cbe6235fe477365773c","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"賁"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (23,32,'{"name":"剥","judgment":"不利。有攸往。","image":"山附地上，剝；上以厚下，安宅。","yaoTexts":["初六：剝牀以足，蔑貞凶。","六二：剝牀以辨，蔑貞凶。","六三：剝之，无咎。","六四：剝牀以膚，凶。","六五：貫魚，以宮人寵，无不利。","上九：碩果不食，君子德車，小人剝廬。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645800","sourceTitle":"《周易》剝卦 · 经文与大象","sourceRevision":10645800,"sourceSha256":"641e20b6320b0c6d6bce4b0856297382547a9ae0f5b4da7ea219944208773090","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"剝"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (24,1,'{"name":"复","judgment":"亨。出入无疾，朋來无咎。反復其道，七日來復，利有攸往。","image":"雷在地中，復；先王以至日閉關，商旅不行，后不省方。","yaoTexts":["初九：不遠復，无祇悔，元吉。","六二：休復，吉。","六三：頻復，厲无咎。","六四：中行獨復。","六五：敦復，无悔。","上六：迷復，凶，有災眚。用行師，終有大敗，以其國君，凶；至于十年，不克征。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643037","sourceTitle":"《周易》復卦 · 经文与大象","sourceRevision":10643037,"sourceSha256":"f798cd72e1c558fb9bcd640ee52ba089ca7b0f6f5be3e26c804c8a7733a17b5a","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"復"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (25,57,'{"name":"无妄","judgment":"元亨。利貞。其匪正有眚，不利有攸往。","image":"天下雷行，物與无妄；先王以茂對時，育萬物。","yaoTexts":["初九：无妄，往吉。","六二：不耕穫，不菑畬，則利有攸往。","六三：无妄之災，或繫之牛，行人之得，邑人之災。","九四：可貞，无咎。","九五：无妄之疾，勿藥有喜。","上九：无妄，行有眚，无攸利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645038","sourceTitle":"《周易》无妄卦 · 经文与大象","sourceRevision":10645038,"sourceSha256":"c11bc5a60fde2c199374195527cee4102ef5e5b755b7cb2bb44454eec95fd310","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"无妄"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (26,39,'{"name":"大畜","judgment":"利貞，不家食吉，利涉大川。","image":"天在山中，大畜；君子以多識前言往行，以畜其德。","yaoTexts":["初九：有厲利已。","九二：輿說輹。","九三：良馬逐，利艱貞，吉。日閑輿衛，利有攸往。","六四：童牛之告，元吉。","六五：豶豕之牙，吉。","上九：何天之衢，亨。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646304","sourceTitle":"《周易》大畜卦 · 经文与大象","sourceRevision":10646304,"sourceSha256":"5cfe64d4db6fea5edd781f4ee13b6465e27d62e1cb1ee777121b158700bbfeaa","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"大畜"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (27,33,'{"name":"颐","judgment":"貞吉。觀頤，自求口實。","image":"山下有雷，頤；君子以慎言語，節飲食。","yaoTexts":["初九：舍爾靈龜，觀我朵頤，凶。","六二：顛頤，拂經，于丘頤，征凶。","六三：拂頤，貞凶，十年勿用，无攸利。","六四：顛頤吉，虎視眈眈，其欲逐逐，无咎。","六五：拂經，居貞吉，不可涉大川。","上九：由頤，厲吉，利涉大川。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643091","sourceTitle":"《周易》頤卦 · 经文与大象","sourceRevision":10643091,"sourceSha256":"d356ddc403ae8a2923c8805df8854b44b65eaa39c430b41a7924ea55593f320a","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"頤"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (28,30,'{"name":"大过","judgment":"棟橈，利有攸往，亨。","image":"澤滅木，大過。君子以獨立不懼，遯世无悶。","yaoTexts":["初六：藉用白茅，无咎。","九二：枯楊生稊，老夫得其女妻，无不利。","九三：棟橈，凶。","九四：棟隆，吉。有它吝。","九五：枯楊生華，老婦得其士夫，无咎无譽。","上六：過涉滅頂，凶，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645184","sourceTitle":"《周易》大過卦 · 经文与大象","sourceRevision":10645184,"sourceSha256":"1249e5a4ebb965dc31392541cf4f2b2892361c3b7a147eea0d79d7050778490f","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"大過"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (29,18,'{"name":"坎","judgment":"有孚，維心亨。行有尚。","image":"水洊至，習坎；君子以常德行，習教事。","yaoTexts":["初六：習坎，入于坎窞，凶。","九二：坎有險，求小得。","六三：來之坎坎，險且枕，入于坎窞，勿用。","六四：尊酒簋，貳用缶。内約自牖，終无咎。","九五：坎不盈，禔既平，无咎。","上六：係用徽纆，寘于叢棘，三歲不得，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646381","sourceTitle":"《周易》坎卦 · 经文与大象","sourceRevision":10646381,"sourceSha256":"67649ec92aad923c487b99d0eadb244f47fd81ac9ec1fc41c991cae52fe8c980","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"坎"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (30,45,'{"name":"离","judgment":"利貞。亨。畜牝牛，吉。","image":"明兩作離，大人以繼明照于四方。","yaoTexts":["初九：履錯然，敬之无咎。","六二：黃離，元吉。","九三：日昃之離，不鼓缶而歌，則大耋之差，凶。","九四：突如其來如，焚如，死如，棄如。","六五：出涕沱若，戚嗟若，吉。","上九：王用出征，有嘉折首，獲匪其醜，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646424","sourceTitle":"《周易》離卦 · 经文与大象","sourceRevision":10646424,"sourceSha256":"441acca23398f8f80692371d6f6210c53ee2d945f3f77df0f649b2eb9da02ec9","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"離"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (31,28,'{"name":"咸","judgment":"亨。利貞。取女吉。","image":"山上有澤，咸；君子以虛受人。","yaoTexts":["初六：咸其拇。","六二：咸其腓，凶，居吉。","九三：咸其股，執其隨，往吝。","九四：貞吉悔亡，憧憧往來，朋從爾思。","九五：咸其脢，无悔。","上六：咸其輔，頰，舌。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646450","sourceTitle":"《周易》咸卦 · 经文与大象","sourceRevision":10646450,"sourceSha256":"fb35b42cf24d00ebc1532456ea7832c2d30f99fa52ba76c778451aa31a8d85ff","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"咸"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (32,14,'{"name":"恒","judgment":"亨，无咎。利貞，利有攸往。","image":"雷風，恆；君子以立不易方。","yaoTexts":["初六：浚恆，貞凶，无攸利。","九二：悔亡。","九三：不恆其德，或承之羞，貞吝。","九四：田无禽。","六五：恆其德，貞，婦人吉，夫子凶。","上六：震恆，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646486","sourceTitle":"《周易》恒卦 · 经文与大象","sourceRevision":10646486,"sourceSha256":"e9c83f30c75539487013066246e4f8cbf27bde372ec46b4e47c609e0622b67bc","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"恒"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (33,60,'{"name":"遁","judgment":"亨。小利貞。","image":"天下有山，遯；君子以遠小人，不惡而嚴。","yaoTexts":["初六：遯尾，厲，勿用有攸往。","六二：執之用黃牛之革，莫之勝說。","九三：係遯，有疾厲，畜臣妾吉。","九四：好遯君子吉，小人否。","九五：嘉遯，貞吉。","上九：肥遯，无不利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645108","sourceTitle":"《周易》遯卦 · 经文与大象","sourceRevision":10645108,"sourceSha256":"2676bbe35fe01a331f62ce09665031ce05435a5b8f9bc2bb49a4ae761c0751fb","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"遯"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (34,15,'{"name":"大壮","judgment":"利貞。","image":"雷在天上，大壯；君子以非禮弗履。","yaoTexts":["初九：壯于趾，征凶，有孚。","九二：貞吉。","九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。","九四：貞吉悔亡，藩決不羸，壯于大轝之腹。","六五：喪羊于易，无悔。","上六：羝羊觸藩，不能退，不能遂，无攸利，艱則吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646529","sourceTitle":"《周易》大壯卦 · 经文与大象","sourceRevision":10646529,"sourceSha256":"cddc93eed027f6a988901d305169ec51ba9b38c783b14488de6f1b141aec868b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"大壯"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (35,40,'{"name":"晋","judgment":"康侯用錫馬蕃庶，晝日三接。","image":"明出地上，晉；君子以自昭明德。","yaoTexts":["初六：晉如，摧如，貞吉。罔孚，裕无咎。","六二：晉如，愁如，貞吉。受茲介福，于其王母。","六三：眾允，悔亡。","九四：晉如鼫鼠，貞厲。","六五：悔亡，矢得勿恤，往吉无不利。","上九：晉其角，維用伐邑，厲吉无咎，貞吝。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646579","sourceTitle":"《周易》晉卦 · 经文与大象","sourceRevision":10646579,"sourceSha256":"7322474e504b7919ee7f29188f90aade0c384a2e5f4570de3eea3c8cbb083354","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"晉"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (36,5,'{"name":"明夷","judgment":"利艱貞。","image":"明入地中，明夷；君子以蒞眾，用晦而明。","yaoTexts":["初九：明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。","六二：明夷，夷于左股，用拯馬壯，吉。","九三：明夷于南狩，得其大首，不可疾貞。","六四：入于左腹，獲明夷之心，于出門庭。","六五：箕子之明夷，利貞。","上六：不明晦，初登于天，後入于地。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10644507","sourceTitle":"《周易》明夷卦 · 经文与大象","sourceRevision":10644507,"sourceSha256":"4d341536c62fa6e76cf02602e433eaff9a377efc8ed19258b85ae6ada8aea0ab","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"明夷"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (37,53,'{"name":"家人","judgment":"利女貞。","image":"風自火出，家人；君子以言有物，而行有恆。","yaoTexts":["初九：閑有家，悔亡。","六二：无攸遂，在中饋，貞吉。","九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。","六四：富家，大吉。","九五：王假有家，勿恤。吉。","上九：有孚威如，終吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405005","sourceTitle":"《周易》家人卦 · 经文与大象","sourceRevision":2405005,"sourceSha256":"0179c8e76f2ef04ee811c1acf142f707d29083fe324de7c4cd086ceb47f79c99","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"家人"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (38,43,'{"name":"睽","judgment":"小事吉。","image":"上火下澤，睽；君子以同而異。","yaoTexts":["初九：悔亡，喪馬勿逐，自復；見惡人无咎。","九二：遇主于巷，无咎。","六三：見輿曳，其牛𧤊，其人天且劓，无初有終。","九四：睽孤，遇元夫，交孚，厲无咎。","六五：悔亡，厥宗噬膚，往何咎。","上九：睽孤， 見豕負涂，載鬼一車， 先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646622","sourceTitle":"《周易》睽卦 · 经文与大象","sourceRevision":10646622,"sourceSha256":"e992371a0dc8ee58aba5f44f8ede6205712dbdad25edb7c030a1dcf12f067706","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"睽"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (39,20,'{"name":"蹇","judgment":"利西南，不利東北；利見大人，貞吉。","image":"山上有水，蹇；君子以反身修德。","yaoTexts":["初六：往蹇，來譽。","六二：王臣蹇蹇，匪躬之故。","九三：往蹇來反。","六四：往蹇來連。","九五：大蹇朋來。","上六：往蹇來碩，吉；利見大人。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405036","sourceTitle":"《周易》蹇卦 · 经文与大象","sourceRevision":2405036,"sourceSha256":"4fca7850987f383c2a66b195c5c35c5f39be0c41877c5607013d6a9858d7066b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"蹇"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (40,10,'{"name":"解","judgment":"利西南，无所往，其來復吉。有攸往，夙吉。","image":"雷雨作，解；君子以赦過宥罪。","yaoTexts":["初六：无咎。","九二：田獲三狐，得黃矢，貞吉。","六三：負且乘，致寇至，貞吝。","九四：解而拇，朋至斯孚。","六五：君子惟有解，吉；有孚于小人。","上六：公用射隼，于高墉之上，獲之，无不利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646666","sourceTitle":"《周易》解卦 · 经文与大象","sourceRevision":10646666,"sourceSha256":"46fd421e644b9e766810bc08b912d61b680d17a3b5a420311d5bf75289a831f2","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"解"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (41,35,'{"name":"损","judgment":"有孚，元吉。无咎，可貞，利有攸往。曷之用？二簋可用享。","image":"山下有澤，損；君子以懲忿窒欲。","yaoTexts":["初九：祀事遄往，无咎，酌損之。","九二：利貞，征凶，弗損益之。","六三：三人行，則損一人；一人行，則得其友。","六四：損其疾，使遄有喜，无咎。","六五：或益之，十朋之龜弗克違，元吉。","上九：弗損益之，无咎，貞吉，利有攸往，得臣无家。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646704","sourceTitle":"《周易》損卦 · 经文与大象","sourceRevision":10646704,"sourceSha256":"35cd31fa7274be23f261cdbeedea2764f755f2b9216e187ebd7cb19f104e7cea","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"損"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (42,49,'{"name":"益","judgment":"利有攸往。利涉大川。","image":"風雷，益；君子以見善則遷，有過則改。","yaoTexts":["初九：利用為大作，元吉，无咎。","六二：或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉。","六三：益之用凶事，无咎。有孚中行，告公用圭。","六四：中行，告公從。利用為依遷國。","九五：有孚惠心，勿問元吉。有孚惠我德。","上九：莫益之，或擊之，立心勿恆，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646726","sourceTitle":"《周易》益卦 · 经文与大象","sourceRevision":10646726,"sourceSha256":"b6b667ee48181cb28e9ba3a96f5e9f209d30a5a50396594c55b5260b5cb29aee","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"益"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (43,31,'{"name":"夬","judgment":"揚于王庭，孚號，有厲，告自邑，不利即戎，利有攸往。","image":"澤上于天，夬；君子以施祿及下，居德則忌。","yaoTexts":["初九：壯于前趾，往不勝為咎。","九二：惕號，莫夜有戎，勿恤。","九三：壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，无咎。","九四：臀无膚，其行次且。牽羊悔亡，聞言不信。","九五：莧陸夬夬，中行无咎。","上六：无號，終有凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405003","sourceTitle":"《周易》夬卦 · 经文与大象","sourceRevision":2405003,"sourceSha256":"1dbda1e9e07a19fe4ff04491bf7f99b3b9c501702773972d647745c2c5f4b0aa","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"夬"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (44,62,'{"name":"姤","judgment":"女壯，勿用取女。","image":"天下有風，姤；后以施命誥四方。","yaoTexts":["初六：系于金柅，貞吉，有攸往，見凶，羸豕，孚，蹢躅。","九二：包有魚，无咎，不利賓。","九三：臀无膚，其行次且，厲，无大咎。","九四：包无魚，起凶。","九五：以杞包瓜，含章，有隕自天。","上九：姤其角，吝，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646826","sourceTitle":"《周易》姤卦 · 经文与大象","sourceRevision":10646826,"sourceSha256":"6b32ae120b58931145ddff8085f5c56e45f7c52c3a1cb6a5c6a49d3b358819e3","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"姤"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (45,24,'{"name":"萃","judgment":"王假有廟，利見大人，亨。利貞。用大牲吉，利有攸往。","image":"澤上于地，萃；君子以除戎器，戒不虞。","yaoTexts":["初六：有孚不終，乃亂乃萃，若號一握為笑，勿恤，往无咎。","六二：引吉，无咎，孚乃利用禴。","六三：萃如，嗟如，无攸利，往无咎，小吝。","九四：大吉，无咎。","九五：萃有位，无咎。匪孚，元永貞，悔亡。","上六：齎資涕洟，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647546","sourceTitle":"《周易》萃卦 · 经文与大象","sourceRevision":10647546,"sourceSha256":"f353e767fdeeca38561dfe43a34c587366154bad4ab6e5899924045b28da1c14","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"萃"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (46,6,'{"name":"升","judgment":"元亨，用見大人，勿恤，南征吉。","image":"地中生木，升；君子以順德，積小以高大。","yaoTexts":["初六：允升，大吉。","九二：孚乃利用禴，无咎。","九三：升虛邑。","六四：王用享于岐山，吉无咎。","六五：貞吉，升階。","上六：冥升，利于不息之貞。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10646879","sourceTitle":"《周易》升卦 · 经文与大象","sourceRevision":10646879,"sourceSha256":"443fb95dd115611d330e6ff8c5e71cde43295b15c5004bd1e2e7ecdf4754f742","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"升"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (47,26,'{"name":"困","judgment":"亨，貞大人吉，无咎，有言不信。","image":"澤无水，困；君子以致命遂志。","yaoTexts":["初六：臀困于株木，入于幽谷，三歲不覿。","九二：困于酒食，朱紱方來，利用亨祀，征凶，无咎。","六三：困于石，據于蒺蔾，入于其宮，不見其妻，凶。","九四：來荼荼，困于金轝，吝，有終。","九五：劓刖，困于赤紱，乃徐有說，利用祭祀。","上六：困于葛藟，于臲卼，曰動悔。有悔，征吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647032","sourceTitle":"《周易》困卦 · 经文与大象","sourceRevision":10647032,"sourceSha256":"cc243ac371a6fa4df22160bc14f1d5ce8802849a778522758ec24b87fa562b8b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"困"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (48,22,'{"name":"井","judgment":"改邑不改井，无喪无得，往來井井。汔至亦未繘井。羸其瓶，凶。","image":"木上有水，井；君子以勞民勸相。","yaoTexts":["初六：井泥不食，舊井无禽。","九二：井谷射鮒，瓮敝漏。","九三：井渫不食，為我心惻，可用汲，王明，並受其福。","六四：井甃，无咎。","九五：井冽，寒泉食。","上六：井收勿幕，有孚元吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645240","sourceTitle":"《周易》井卦 · 经文与大象","sourceRevision":10645240,"sourceSha256":"1ab27335076e1c166642c60b9f31789337a7da0c66ec4e3d9f28632786ff0914","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"井"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (49,29,'{"name":"革","judgment":"已日乃孚，元亨。利貞。悔亡。","image":"澤中有火，革；君子以治歷明時。","yaoTexts":["初九：鞏用黃牛之革。","六二：已日乃革之，征吉，无咎。","九三：征凶，貞厲，革言三就，有孚。","九四：悔亡，有孚改命，吉。","九五：大人虎變，未占有孚。","上六：君子豹變，小人革面，征凶，居貞吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643173","sourceTitle":"《周易》革卦 · 经文与大象","sourceRevision":10643173,"sourceSha256":"095de39170ac0e2407fbebd131f3957b08f13d1aeea25eed4f331aa672fde643","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"革"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (50,46,'{"name":"鼎","judgment":"元吉，亨。","image":"木上有火，鼎；君子以正位凝命。","yaoTexts":["初六：鼎顛趾，利出否，得妾以其子，无咎。","九二：鼎有實，我仇有疾，不我能即，吉。","九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。","九四：鼎折足，覆公餗，其刑渥，凶。","六五：鼎黃耳金鉉，利貞。","上九：鼎玉鉉，大吉，无不利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647086","sourceTitle":"《周易》鼎卦 · 经文与大象","sourceRevision":10647086,"sourceSha256":"f42593c252a3f9a3c5f3e0005959c887acb653016eef0b887bf51c129b841fa8","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"鼎"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (51,9,'{"name":"震","judgment":"亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。","image":"洊雷，震；君子以恐懼修省。","yaoTexts":["初九：震來虩虩，後笑言啞啞，吉。","六二：震來厲，億喪貝，躋于九陵，勿逐，七日得。","六三：震蘇蘇，震行无眚。","九四：震遂泥。","六五：震往來厲，億无喪，有事。","上六：震索索，視矍矍，征凶。震不于其躬，于其鄰，无咎。婚媾有言。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10644930","sourceTitle":"《周易》震卦 · 经文与大象","sourceRevision":10644930,"sourceSha256":"a91ae3f5544413961abcc2d134f79310de1f7bab2c81f7f29a42d309a75ad26a","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"震"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (52,36,'{"name":"艮","judgment":"艮其背，不獲其身，行其庭，不見其人，无咎。","image":"兼山，艮；君子以思不出其位。","yaoTexts":["初六：艮其趾，无咎，利永貞。","六二：艮其腓，不拯其隨，其心不快。","九三：艮其限，裂其夤，厲閽心。","六四：艮其身，无咎。","六五：艮其輔，言有孚，悔亡。","上九：敦艮，吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647135","sourceTitle":"《周易》艮卦 · 经文与大象","sourceRevision":10647135,"sourceSha256":"58c8311a879b6c5e764365d0beb1c946ae2a2e63784e1e1d6a946f387a0379ee","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"艮"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (53,52,'{"name":"渐","judgment":"女歸吉，利貞。","image":"山上有木，漸；君子以居賢德，善俗。","yaoTexts":["初六：鴻漸于干，小子厲，有言，无咎。","六二：鴻漸于磐，飲食衎衎，吉。","九三：鴻漸于陸，夫征不復，婦孕不育，凶；利禦寇。","六四：鴻漸于木，或得其桷，无咎。","九五：鴻漸于陵，婦三歲不孕，終莫之勝，吉。","上九：鴻漸于陸，其羽可用為儀，吉。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2560535","sourceTitle":"《周易》漸卦 · 经文与大象","sourceRevision":2560535,"sourceSha256":"46da172e6576ba774f6c61741a2d566014f5e5fc90c1065251cb80ccd89b28d7","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"漸"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (54,11,'{"name":"归妹","judgment":"征凶，无攸利。","image":"澤上有雷，歸妹；君子以永終知敝。","yaoTexts":["初九：歸妹以娣，跛能履，征吉。","九二：眇能視，利幽人之貞。","六三：歸妹以須，反歸以娣。","九四：歸妹愆期，遲歸有時。","六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。","上六：女承筐无實，士刲羊无血，无攸利。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647182","sourceTitle":"《周易》歸妹卦 · 经文与大象","sourceRevision":10647182,"sourceSha256":"3b875fda93e1388dd9359d5185626e56e542344e07efe0659b02512595c992fd","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"歸妹"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (55,13,'{"name":"丰","judgment":"亨。王假之，勿憂，宜日中。","image":"雷電皆至，豐；君子以折獄致刑。","yaoTexts":["初九：遇其配主，雖旬无咎，往有尚。","六二：豐其蔀，日中見斗，往得疑疾，有孚發若，吉。","九三：豐其沛，日中見沬，折其右肱，无咎。","九四：豐其蔀，日中見斗，遇其夷主，吉。","六五：來章，有慶譽，吉。","上六：豐其屋，蔀其家，窺其戶，闃其无人，三歲不觌，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10645290","sourceTitle":"《周易》豐卦 · 经文与大象","sourceRevision":10645290,"sourceSha256":"decc267b9a05f7779a16ca01bc00fce9bff4e650fd3b1195d0f97d91297df302","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"豐"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (56,44,'{"name":"旅","judgment":"小亨，旅貞吉。","image":"山上有火，旅；君子以明慎用刑，而不留獄。","yaoTexts":["初六：旅瑣瑣，斯其所取災。","六二：旅即次，懷其資，得僮僕貞。","九三：旅焚其次，喪其僮僕，貞厲。","九四：旅于處，得其資斧，我心不快。","六五：射雉一矢亡，終以譽命。","上九：鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647234","sourceTitle":"《周易》旅卦 · 经文与大象","sourceRevision":10647234,"sourceSha256":"3e8aed4bcd7651b4afde4fbfa7451fd15d632ad313d8760c1dda7d3d3c49e819","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"旅"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (57,54,'{"name":"巽","judgment":"小亨。利有攸往。利見大人。","image":"隨風，巽；君子以申命行事。","yaoTexts":["初六：進退，利武人之貞。","九二：巽在牀下，用史巫紛若，吉无咎。","九三：頻巽，吝。","六四：悔亡，田獲三品。","九五：貞吉悔亡，无不利。无初有終，先庚三日，後庚三日，吉。","上九：巽在牀下，喪其資斧，貞凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10644966","sourceTitle":"《周易》巽卦 · 经文与大象","sourceRevision":10644966,"sourceSha256":"99a815af7cfac36d8d46784002467f6e70babf49e7fe4bb930976d0e78dc066c","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"巽"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (58,27,'{"name":"兑","judgment":"亨。利貞。","image":"麗澤，兌；君子以朋友講習。","yaoTexts":["初九：和兌，吉。","九二：孚兌，吉，悔亡。","六三：來兌，凶。","九四：商兌，未寧，介疾有喜。","九五：孚于剝，有厲。","上六：引兌。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2404993","sourceTitle":"《周易》兌卦 · 经文与大象","sourceRevision":2404993,"sourceSha256":"0ecebe0d070dcd3cdf07019a3f1d578cbcd4d1bb441c48b8536bb596e3e49850","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"兌"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (59,50,'{"name":"涣","judgment":"亨，王假有廟，利涉大川，利貞。","image":"風行水上，渙；先王以享于帝立廟。","yaoTexts":["初六：用拯馬壯，吉，悔亡。","九二：渙奔其机，悔亡。","六三：渙其躬，无悔。","六四：渙其群，元吉。渙有丘，匪夷所思。","九五：渙汗其大號，渙王居，无咎。","上九：渙其血，去逖出，无咎。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647580","sourceTitle":"《周易》渙卦 · 经文与大象","sourceRevision":10647580,"sourceSha256":"9c8c9b4298fa8429c00ece4a08821a83f9a5692f9bba09eb26cd2e180850c76e","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"渙"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (60,19,'{"name":"节","judgment":"亨。苦節不可貞。","image":"澤上有水，節；君子以制數度，議德行。","yaoTexts":["初九：不出戶庭，无咎。","九二：不出門庭，凶。","六三：不節若，則嗟若，无咎。","六四：安節，亨。","九五：甘節，吉；往有尚。","上六：苦節，貞凶，悔亡。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2405027","sourceTitle":"《周易》節卦 · 经文与大象","sourceRevision":2405027,"sourceSha256":"a017661595c6358621214894a41885648d4e2fe71af0d43ebd9f7b3f66517bcf","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"節"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (61,51,'{"name":"中孚","judgment":"豚魚吉，利涉大川，利貞。","image":"澤上有風，中孚；君子以議獄緩死。","yaoTexts":["初九：虞吉，有它不燕。","九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。","六三：得敵，或鼓或罷，或泣或歌。","六四：月既望，馬匹亡，无咎。","九五：有孚攣如，无咎。","上九：翰音登于天，貞凶。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647425","sourceTitle":"《周易》中孚卦 · 经文与大象","sourceRevision":10647425,"sourceSha256":"9048c101757a1c3a0f5e7ec3d79e0fa22ba121babbf7fc083b8a48e1a0514e2b","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"中孚"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (62,12,'{"name":"小过","judgment":"亨。利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。","image":"山上有雷，小過；君子以行過乎恭，喪過乎哀，用過乎儉。","yaoTexts":["初六：飛鳥以凶。","六二：過其祖，遇其妣；不及其君，遇其臣；无咎。","九三：弗過防之，從或戕之，凶。","九四：无咎，弗過遇之。往厲必戒，勿用永貞。","六五：密雲不雨，自我西郊，公弋取彼在穴。","上六：弗遇過之，飛鳥離之，凶，是謂災眚。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10643238","sourceTitle":"《周易》小過卦 · 经文与大象","sourceRevision":10643238,"sourceSha256":"899bcfc5e793f63761f01098bc6997cbec4c71be84f183f763c553e69075f1cd","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"小過"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (63,21,'{"name":"既济","judgment":"亨小。利貞。初吉終亂。","image":"水在火上，既濟；君子以思患而豫防之。","yaoTexts":["初九：曳其輪，濡其尾，无咎。","六二：婦喪其茀，勿逐，七日得。","九三：高宗伐鬼方，三年克之，小人勿用。","六四：繻有衣袽，終日戒。","九五：東鄰殺牛，不如西鄰之禴祭，實受其福。","上六：濡其首，厲。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=2572417","sourceTitle":"《周易》既濟卦 · 经文与大象","sourceRevision":2572417,"sourceSha256":"e9099522d8013177a9316c8fc499a10b80d50edd18b3401cbd79b2d31ab58d78","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"既濟"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.iching_hexagrams(number,line_bits,payload) values (64,42,'{"name":"未济","judgment":"亨。小狐汔濟，濡其尾，无攸利。","image":"火在水上，未濟；君子以慎辨物居方。","yaoTexts":["初六：濡其尾，吝。","九二：曳其輪，貞吉。","六三：未濟，征凶，利涉大川。","九四：貞吉，悔亡，震用伐鬼方，三年有賞于大國。","六五：貞吉，无悔，君子之光，有孚，吉。","上九：有孚于飲酒，无咎，濡其首，有孚失是。"],"useText":null,"sourceUrl":"https://zh.wikisource.org/w/index.php?oldid=10647450","sourceTitle":"《周易》未濟卦 · 经文与大象","sourceRevision":10647450,"sourceSha256":"9dcd6ad074f7d0633872e3e83665e86bd3d2bc19a3ae23cb4ff0eb044e2b4a83","textKind":"primary-text","license":"Ancient original text: public domain; Wikisource transcription attribution retained; CC BY-SA 4.0 where applicable.","sourceName":"未濟"}'::jsonb) on conflict (number) do update set line_bits=excluded.line_bits,payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('iching','{"methodId":"iching","scene":"study","kind":"coins","title":"从天与地，读懂行动与承载","concept":"健与厚德","observe":"三枚铜钱逐次落下，六爻从下往上形成。卦画记录变化，不是吉凶分数。","understand":"《乾·象》说“天行健，君子以自强不息”；《坤·象》说“地势坤，君子以厚德载物”。前者借天的运行谈持续修养，后者借地的承载谈德行与容纳。二者可以并读，不是给人贴强弱标签。","practice":"想一件正在学习的事：你能持续练习的是什么？又需要为谁提供支持？分别写一句，比较“健”与“厚”的行动。","distinction":"此处白话和练习为现代学习设计。卦辞、爻辞与《象传》属于不同文本层次；多动爻的取辞规则也因学派而异。","symbols":["初","二","三","四","五","上"],"stages":["三钱成一爻","由下向上积六爻","动爻变，静爻留"],"sourceTitle":"《周易》经文与《象传》","sourceUrl":"https://zh.wikisource.org/wiki/周易"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('bazi','{"methodId":"bazi","scene":"study","kind":"pillars","title":"把一个时刻放进历法","concept":"干支与四时","observe":"年、月、日、时四柱依次展开。月柱与节气相连，不能只按公历月份替换。","understand":"干支是一种循环记时语言。先认识节令、季节和五行关系，再读命理解释，能把历法知识与后来的解释传统分开。","practice":"比较同一地点冬至与夏至的日常生活。哪些变化来自环境？哪些判断只是象征联想？","distinction":"排盘是规则计算，吉凶和人格解释属于传统解释；不能从文化模型推出一个人的固定价值。","symbols":["年","月","日","时"],"stages":["确认出生资料","四柱依次展开","对照节令与五行"],"sourceTitle":"Atlas 编写 · 干支与节令入门"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('bazi-relationship','{"methodId":"bazi-relationship","scene":"study","kind":"pillars","title":"关系是两个人的协作","concept":"差异与互补","observe":"两组四柱并排，观察相同与不同的位置，不把配对压成一个总分。","understand":"本课借五行关系解释“互补”如何成为一种叙事。传统配对术有时代背景；现实关系需要沟通、尊重与协商。","practice":"各写一个你们处理分歧的习惯，再找出能协作的地方。把实际经历与象征解释分栏记录。","distinction":"这里不是关系成败的判决，也不把出生资料当作同意或信任的替代品。","symbols":["甲方","乙方","相同","差异"],"stages":["并列两份资料","看见结构差异","回到真实的沟通"],"sourceTitle":"Atlas 编写 · 关系反思练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('tarot','{"methodId":"tarot","scene":"cards","kind":"cards","title":"一副牌也是一部图像史","concept":"图像与叙事","observe":"留意牌中人物、器物、姿态和牌阵位置，再说出自己的联想。","understand":"博物馆所藏的早期塔罗来自十五世纪意大利纸牌文化。早期游戏牌与后来的占卜读法需要分开；同一图像在不同牌系中也可能有不同解释。","practice":"先描述你实际看见的三个细节，再写一句联想。比较两者：哪些在图上，哪些来自你的经验？","distinction":"欧洲不只有一种文化。不能把通用塔罗称作西班牙独有的古老占卜；本应用现代牌阵也不是早期游戏规则。","symbols":["所见","联想","行动"],"stages":["洗牌与停驻","翻开图像","把位置连成叙事"],"sourceTitle":"大都会艺术博物馆 · 塔罗的历史与结构","sourceUrl":"https://www.metmuseum.org/ja/perspectives/tarot-2"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('dream','{"methodId":"dream","scene":"reflection","kind":"ripples","title":"梦境先从你的叙述开始","concept":"叙事的多种读法","observe":"先记录场景、情绪和细节，再分别尝试民俗、文学或心理反思的读法。","understand":"同一个梦中意象没有全世界通用的单一答案。家乡故事、个人经历和当下感受会改变你对它的理解。","practice":"写下梦中的一件物品。它在家乡故事里代表什么？在你自己的生活里又意味着什么？","distinction":"本课为跨文化比较练习，不把梦当作事实证据；AI 解释会与原典和个人记录分开。","symbols":["场景","情绪","回忆"],"stages":["记录梦境","并列不同视角","留下自己的解释"],"sourceTitle":"Atlas 编写 · 梦境叙事练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('qimen','{"methodId":"qimen","scene":"courtyard","kind":"grid","title":"在时间与方位之间思考","concept":"时位与布局","observe":"九宫格逐格展开，天干、门、星等符号各有层次。","understand":"读盘先说明排局方法、时间和地点，再比较同一规则下的结构。把“选时择位”的文化语言与实际路线信息并列，才知道它怎样组织问题。","practice":"以一次出行为例，列出真实交通限制，再看盘面如何描述方向。哪些信息能调查，哪些是传统取象？","distinction":"拆补、置闰等口径可能产生差异；本课演示九宫阅读顺序，不冒充一种完整传承的仪轨。","symbols":["巽","离","坤","震","中","兑","艮","坎","乾"],"stages":["核对时地与局法","九宫布列","区分现实信息与取象"],"sourceTitle":"Atlas 编写 · 九宫读盘入门"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('ziwei','{"methodId":"ziwei","scene":"western","kind":"orbit","title":"把人生领域画成十二宫","concept":"宫位是阅读位置","observe":"环绕的宫位先出现，再观察星曜落在哪些位置。","understand":"十二宫把家庭、事业等领域并置，是一种分领域讲述人生的方式。名称里的星曜并不等同于天空中每一颗真实恒星的位置。","practice":"选一个宫位，先写真实经历，再写盘面给你的提问。你认同或不认同的理由是什么？","distinction":"先核对历法、时辰与流派设置，避免把软件口径差异当作命运发生变化。","symbols":["命","财","官","迁"],"stages":["核对时辰","安宫与布星","逐领域阅读"],"sourceTitle":"Atlas 编写 · 紫微宫位阅读"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('liuyao','{"methodId":"liuyao","scene":"study","kind":"coins","title":"一幅卦画，两种阅读角度","concept":"世应与问题角色","observe":"六次掷钱记录同一组爻，随后叠加世应、纳甲和六亲标签。","understand":"周易经文阅读与纳甲六爻可以使用同一卦画，却不采用完全相同的解释体系。“世”“应”把观察者和所问对象放进关系结构。","practice":"为一件具体事情写下“我是谁、对象是谁、缺少什么信息”。再与世应标记比较，不把标签误当事实。","distinction":"动爻与变卦必须从原始投掷推导。旺衰这里只作月令基础提示，完整断法还需要日辰、旬空、伏神等。","symbols":["初","二","三","四","五","上"],"stages":["六次投掷成卦","标明世应与六亲","比较动变与实际问题"],"sourceTitle":"《周易》卦画；Atlas 纳甲学习说明","sourceUrl":"https://zh.wikisource.org/wiki/周易"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('meihua','{"methodId":"meihua","scene":"courtyard","kind":"coins","title":"从数字进入象与变化","concept":"体用与互卦","observe":"先定上下卦，再看动爻；互卦取中间四爻，不能另行随机抽取。","understand":"象数阅读会把数字、方位和自然景象联系起来。文化学习的关键，是看见这种联想如何建立，而不是把所有偶然当成确定征兆。","practice":"用相同的两个数字重新演算，检查上下卦、动爻与互卦是否保持一致。再写下自己的现实判断。","distinction":"本应用声明自己的取数规则。时间法采用农历年月日时口径，与其他取数法应分开比较。","symbols":["上卦","下卦","互卦","动爻"],"stages":["取数定上下卦","中爻组成互卦","动爻决定体用"],"sourceTitle":"Atlas 编写 · 象数结构练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('western','{"methodId":"western","scene":"western","kind":"orbit","title":"天空的位置与人的叙事","concept":"黄道与宫位","observe":"行星沿黄道分布，宫位从上升位置展开；两个圆环表示不同的分类。","understand":"天文位置可以计算，星座与人生主题之间的解释属于占星传统。本课把测量、分类和解释分开，帮助你认识符号语言。","practice":"比较热带黄道与恒星黄道的定义。位置差异来自参考系时，不必把差异理解为其中一方“看错了你”。","distinction":"本应用采用整宫制。核对时区、出生地和宫制后再与其他工具比对。","symbols":["日","月","升","宫"],"stages":["确认时间与地点","定位黄道与上升","分清位置和解释"],"sourceTitle":"Astronomy Engine · 地心位置与坐标说明","sourceUrl":"https://github.com/cosinekitty/astronomy/blob/master/source/js/README.md"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('vedic','{"methodId":"vedic","scene":"vedic","kind":"orbit","title":"观察天空，也认识不同的时间语言","concept":"月宿与周期","observe":"把黄道分区、月亮位置与周期分层展示，先读坐标再读主题。","understand":"斋浦尔的简塔曼塔天文台展示了印度历史上的观测仪器。它可以帮助理解观测文化，但不能为应用中的每一种占星解释提供依据。","practice":"用同一出生时刻比较西占与印度占星：参考黄道、月宿和周期设置分别是什么？","distinction":"手机与网页共用可离线天文计算、近似 Lahiri 岁差与平均月交点。与其他软件比较时，还要统一岁差、交点和宫制。","symbols":["月","宿","时","序"],"stages":["定位月亮","对照恒星黄道","展开周期"],"sourceTitle":"UNESCO · 斋浦尔简塔曼塔天文台","sourceUrl":"https://whc.unesco.org/en/list/1338"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('numerology','{"methodId":"numerology","scene":"study","kind":"numbers","title":"名字变成数字之前","concept":"规则与转写","observe":"字母依照映射变成数字，逐步相加、约简。","understand":"姓名数依赖拼写方案。中文姓名转成拼音，与使用另一种转写可能得到不同结果；这种差异能帮助看见文字系统如何影响象征解释。","practice":"比较你的姓名、拼音与惯用外文名，记录算法输入有什么变化。","distinction":"数字解释是现代象征练习；不把任意字母映射当成普遍的人格测量。","symbols":["字母","数字","求和","约简"],"stages":["确定拼写","逐位相加","说明保留与约简规则"],"sourceTitle":"Atlas 编写 · 数字与转写练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('runes','{"methodId":"runes","scene":"runes","kind":"stones","title":"先认识文字，再谈符号","concept":"铭刻与记忆","observe":"符石翻面后，先观察线条与音值，再读象征联想。","understand":"丹麦国家博物馆把卢恩介绍为日耳曼书写系统。字母史、铭文与现代抽符实践需要区分，不能把今天的抽符流程直接说成维京时代的日常。","practice":"挑一个符号，分别记录它作为文字的功能和今天的联想。思考铭刻为何能成为记忆的载体。","distinction":"本应用抽符属于现代反思玩法；背景插画不是考古复原。","symbols":["ᚠ","ᚢ","ᚦ"],"stages":["静置符石","翻面辨认","区分文字与联想"],"sourceTitle":"丹麦国家博物馆 · 卢恩文字","sourceUrl":"https://en.natmus.dk/historical-knowledge/historical-themes/runes/"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('geomancy','{"methodId":"geomancy","scene":"sand","kind":"dots","title":"让点画成为可追踪的结构","concept":"奇偶与派生","observe":"点画化为单点或双点，四母图继续派生后续图形。","understand":"地占把随机输入变成有规则的推导。英国图书馆所藏手稿中有地占文本；本课展示这种图形组织方式，不将一个现代界面当成全部地域传统。","practice":"记下四母图，在纸上按奇偶规则复算一次。观察哪些步骤是随机，哪些步骤是必然推导。","distinction":"图形规则与事件解读分层；问题宫位及传统版本应明确说明。","symbols":["•","••","•","••"],"stages":["取四组点画","按奇偶派生","对照见证与判官"],"sourceTitle":"英国图书馆 · Harley MS 4166","sourceUrl":"https://searcharchives.bl.uk/catalog/040-002050003"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('lot','{"methodId":"lot","scene":"ritual","kind":"sticks","title":"签诗是一种劝诫语言","concept":"诗、典故与处境","observe":"签筒轻摇，一支签落定；先读诗句，再看典故与白话。","understand":"签诗经常借故事谈等待、守信或行止。不同庙宇和签本不是同一个数据库；本应用的主题签与有出处的传统签必须分开阅读。","practice":"挑一句你不熟悉的诗，把人物、处境和劝诫分别写下来，再寻找它与你的问题的联系。","distinction":"演示不代替具体寺庙礼俗；未核定版本的诗不能标作某庙原签。","symbols":["诗","故","义"],"stages":["停驻与摇签","读签诗","追问典故与处境"],"sourceTitle":"Atlas 编写 · 签诗阅读方法"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('jiaobei','{"methodId":"jiaobei","scene":"ritual","kind":"cups","title":"先把问题问清楚","concept":"礼俗中的确认","observe":"两片筊杯落定，平面与曲面的组合有不同名称。","understand":"本课从提问方式理解礼俗：一个问题是否清楚、是否需要改问、是否愿意接受等待。具体社区的礼仪规则可能不同。","practice":"把“我以后会怎样”改成一个边界清楚的问题。再想想：哪些事情应通过直接沟通确认？","distinction":"模拟投掷并不是神意认证；停止反复追问也可以是体验的一部分。","symbols":["平","曲"],"stages":["明确一件事","两杯落定","读组合并记录"],"sourceTitle":"Atlas 编写 · 杯筊礼俗入门"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('xiangmian','{"methodId":"xiangmian","scene":"reflection","kind":"trace","title":"观察身体，不给人定价","concept":"描述与评价","observe":"先标注自我观察的部位，再把看到的特征与解释分开。","understand":"相术包含历史上的身体象征，也可能带有时代偏见。文化理解需要看见这些局限，而不是根据外貌推断人格或命运。","practice":"把一个评价句改成中性描述，例如把“看起来凶”改成你实际观察到的表情。","distinction":"仅供自我观察和批判性文化学习；不做照片识别，不判断疾病、身份或人的价值。","symbols":["观察","描述","反思"],"stages":["选择自我观察","标注实际所见","辨认解释中的偏见"],"sourceTitle":"Atlas 编写 · 身体象征的批判性阅读"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('palmistry','{"methodId":"palmistry","scene":"reflection","kind":"trace","title":"一只手与日常经验","concept":"身体的象征地图","observe":"沿掌纹观察，再读掌丘和线条在不同读法中的名称。","understand":"掌纹可以成为叙述经验的图像，但线条不是寿命刻度。本课强调不同传统怎样命名身体，而不是从身体决定人生。","practice":"想一件双手学会的技能，记录练习如何改变你的感受，再与象征解释比较。","distinction":"手相说明不用于健康诊断或寿命预测，也不评价他人。","symbols":["掌","线","丘"],"stages":["辨认线条","读名称与象征","联系自己的经验"],"sourceTitle":"Atlas 编写 · 身体与经验练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('fengshui','{"methodId":"fengshui","scene":"courtyard","kind":"orbit","title":"从居住经验理解方位","concept":"空间与照料","observe":"罗盘稳定指向后，再读坐向和九宫分布。","understand":"传统空间语言会把方位与居住经验联系起来。文化学习可以从采光、风、出入口与人的活动开始，再比较传统符号如何描述它们。","practice":"画出房间的一扇窗和一条通路，观察真实光线与通风，提出一项可验证的小调整。","distinction":"手机上的罗盘图不是传感器测量；需自行输入实际坐向。传统建议不替代建筑安全评估。","symbols":["北","东","南","西"],"stages":["确认实际坐向","展开方位","回到可观察的空间"],"sourceTitle":"Atlas 编写 · 空间观察练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('astrodice','{"methodId":"astrodice","scene":"western","kind":"stones","title":"用三个词学习占星语法","concept":"谁、怎样、在哪里","observe":"三枚骰子依次代表行星、星座和宫位，组合成一条提问。","understand":"占星骰子是学习符号语言的现代工具。它借用了占星分类，但没有计算某个真实时刻的天空。","practice":"把一次组合写成开放问题，而不是事件预言。比较“我会成功”与“我怎样表达自己的行动力”。","distinction":"投骰结果不是实际星盘；图示演示与真实掷骰结果分开。","symbols":["行星","星座","宫位"],"stages":["掷三骰","辨认三个维度","组合成开放问题"],"sourceTitle":"Atlas 编写 · 现代占星骰子入门"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('lenormand','{"methodId":"lenormand","scene":"cards","kind":"cards","title":"让日常图像组成一句话","concept":"图像之间的语法","observe":"牌面按位置展开，观察相邻关系，避免只把单张含义相加。","understand":"本课把信件、道路、房屋等日常图像当成叙事词汇。不同牌系与读法的背景要分别说明，不能用塔罗术语覆盖一切纸牌传统。","practice":"拿三个日常物品图像，尝试写两句不同的故事，看看顺序如何改变理解。","distinction":"这是现代读牌练习；没有出处的组合解释应标为作者编写。","symbols":["图像","相邻","语句"],"stages":["排定位置","翻开日常图像","比较组合语义"],"sourceTitle":"Atlas 编写 · 雷诺曼组合阅读"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('oracle','{"methodId":"oracle","scene":"cards","kind":"cards","title":"知道是谁写下这句话","concept":"作者与主题","observe":"抽到一张主题卡后，先看文字与图像，再思考它是否适合你的处境。","understand":"神谕卡没有一个通用古代标准牌库。本应用主题与反思提示属于现代创作，理解作者和设计意图本身也是文化素养。","practice":"选一句提示，写下你接受它的理由，以及在哪种情况下它并不适用。","distinction":"不把现代原创文字包装成失传古籍或神谕。","symbols":["主题","感受","行动"],"stages":["选择主题","揭示提示","保留自己的判断"],"sourceTitle":"Atlas 原创主题卡与反思提示"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('coffee','{"methodId":"coffee","scene":"coffee","kind":"ripples","title":"先有待客，才有杯底故事","concept":"分享与交谈","observe":"咖啡杯落定，杯底痕迹成为聊天的入口。先看真实形状，再讲联想。","understand":"UNESCO 将土耳其咖啡列入非遗，描述其制作与社交传统，也提到以杯底咖啡渣占卜。理解文化不只看符号，还要看谁与谁围坐、怎样待客。","practice":"想象你邀请一位朋友喝咖啡：先问他近况，再一起给一个形状编故事，最后说清哪些只是联想。","distinction":"本应用为符号模拟，不会分析真实咖啡渣照片。也不能把土耳其文化当作整个地中海的统一文化。","symbols":["杯","痕","话"],"stages":["分享一杯咖啡","观察杯底","把联想变成对话"],"sourceTitle":"UNESCO · 土耳其咖啡文化与传统","sourceUrl":"https://ich.unesco.org/en/RL/turkish-coffee-culture-and-tradition-00645"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
insert into public.culture_lessons(method_id,payload) values ('scrying','{"methodId":"scrying","scene":"reflection","kind":"ripples","title":"给模糊的意象留一点空间","concept":"观察与想象","observe":"波纹逐渐平静，留意自己想到了什么，不预设必须看见某种图像。","understand":"镜、水、晶体可以成为凝视的媒介。本课用它们设计现代注意力与创作练习，不把一个画面归给所有文明。","practice":"看一个模糊形状十秒，记下第一联想。换一个角度再看，比较解释是否改变。","distinction":"软件给出的是象征提示，不是感知到超自然信息，也不替你记录实际上没有看到的现象。","symbols":["水","光","影"],"stages":["静观","记录联想","区分所见与想象"],"sourceTitle":"Atlas 原创凝视与反思练习"}'::jsonb) on conflict (method_id) do update set payload=excluded.payload,content_version='2026-10-20';
